   <div className="agent-trade-head"><div><h1>{adminMode?(adminCreating?"Create Trade for Agent":"Trade Submission Queue"):"My Trade Submissions"}</h1><p className="muted">{adminMode?(adminCreating?"Create and assign a trade to an agent.":"Review agent-entered information and uploaded documents before creating a billing and payout transaction."):"Create a trade, upload the supporting documents and submit everything for Trade Admin approval."}</p></div><div style={{display:"flex",gap:8,flexWrap:"wrap"}}>{adminMode&&adminCreating&&<button className="secondary" type="button" onClick={()=>{setAdminCreating(false);setSelected(null);setError("");setMessage("");}}><X size={16}/> Back to Trade Review</button>}{agentCreating&&<button className="secondary" type="button" onClick={()=>{setAgentCreating(false);setSelected(null);setDocs([]);setError("");setMessage("");}}><X size={16}/> Back to Submissions</button>}{selected&&!adminCreating&&<button className="secondary" type="button" onClick={()=>{try{if(!adminMode&&typeof window!=="undefined")window.sessionStorage.removeItem("dv-agent-trade-selected-id");}catch{}setAgentCreating(false);setSelected(null);setDocs([]);setActiveTab("PROPERTY");setError("");setMessage("");}}><X size={16}/> Back to Submissions</button>}{!selected&&!adminCreating&&<button className="secondary" onClick={load}><RefreshCw size={16}/> Refresh</button>}{!adminMode&&<button className="primary" onClick={startNew}><Plus size={16}/> New Trade</button>}{adminMode&&!adminCreating&&<button className="primary" type="button" onClick={startAdminTrade}><Plus size={16}/> Create Trade for Agent</button>}</div></div>
